#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct HeldInput {
    pub left: bool,
    pub right: bool,
    pub up: bool,
    pub down: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum GridError {
    ZeroStep,
    ZeroWidth,
    ZeroHeight,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FixedGrid {
    pub x: usize,
    pub y: usize,
    width: usize,
    height: usize,
    step_ms: u64,
    accumulated_ms: u64,
}

impl FixedGrid {
    pub fn new(width: usize, height: usize, step_ms: u64) -> Result<Self, GridError> {
        if step_ms == 0 {
            return Err(GridError::ZeroStep);
        }
        if width == 0 {
            return Err(GridError::ZeroWidth);
        }
        if height == 0 {
            return Err(GridError::ZeroHeight);
        }
        Ok(Self { x: 0, y: 0, width, height, step_ms, accumulated_ms: 0 })
    }

    pub fn advance(&mut self, elapsed_ms: u64, input: &HeldInput) -> usize {
        self.accumulated_ms = self.accumulated_ms.saturating_add(elapsed_ms);
        let mut steps = 0;
        while self.accumulated_ms >= self.step_ms {
            self.accumulated_ms -= self.step_ms;
            if input.left != input.right {
                if input.left {
                    self.x = self.x.saturating_sub(1);
                } else {
                    self.x = (self.x + 1).min(self.width - 1);
                }
            }
            if input.up != input.down {
                if input.up {
                    self.y = self.y.saturating_sub(1);
                } else {
                    self.y = (self.y + 1).min(self.height - 1);
                }
            }
            steps += 1;
        }
        steps
    }
}
